  const x = (v) => P + ((v.version - 1) / Math.max(1, n)) * (W - 2 * P);
  const y = (s) => H - P - ((s - 1) / 4) * (H - 2 * P);
  const xs = c.versions.length === 1 ? [W / 2] : null;
  const pos = pts.map((v) => [xs ? xs[0] : x(v), y(v.score)]);
  const line = pos.length > 1 ? '<polyline fill="none" stroke="#2563eb" stroke-width="2.5" points="' + pos.map((p) => p[0].toFixed(1) + ',' + p[1].toFixed(1)).join(' ') + '"/>' : '';
  const grid = [1, 3, 5].map((s) => '<line x1="' + P + '" x2="' + (W - P) + '" y1="' + y(s).toFixed(1) + '" y2="' + y(s).toFixed(1) + '" stroke="#e2e8f0"/><text x="4" y="' + (y(s) + 4).toFixed(1) + '" font-size="10" fill="#64748b">' + s + '</text>').join('');
  const th = '<line x1="' + P + '" x2="' + (W - P) + '" y1="' + y(4.5).toFixed(1) + '" y2="' + y(4.5).toFixed(1) + '" stroke="#f59e0b" stroke-dasharray="4 3"/>';
  const dots = pts.map((v, i) => '<circle cx="' + pos[i][0].toFixed(1) + '" cy="' + pos[i][1].toFixed(1) + '" r="4.5" fill="' + (v.gate === 'PASS' ? '#059669' : '#dc2626') + '"><title>v' + E(v.version) + ': ' + E(v.score) + ' / 5 (' + E(v.gate) + ')</title></circle><text x="' + pos[i][0].toFixed(1) + '" y="' + (H - 4) + '" font-size="10" text-anchor="middle" fill="#334155">v' + E(v.version) + '</text>').join('');
  return '<svg class="trend" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="Reviewer score by version for ' + E(c.case_id) + '">' + grid + th + line + dots + '</svg>';
