      (c.controlled ? '<div class="note test">CONTROLLED TEST: a labelled fixture changed the first evaluated draft after real model generation (' + E((a.fixture && a.fixture.description) || 'see fixture record') + '). The omission is an injected fault, not an unprompted model error.</div>' : '') +
      '<div class="compare"><div class="col"><div class="col-h">Initial evaluated draft (v' + E(a.version) + ') &middot; ' + score(a.score) + ' &middot; ' + E(a.gate || 'n/a') + '</div><div class="dl">Subject</div>' + val(a.subject) + '<div class="dl">Body</div>' + pre(a.body) + '</div>' +
      '<div class="col"><div class="col-h">Latest evaluated draft (v' + E(b.version) + ') &middot; ' + score(b.score) + ' &middot; ' + E(b.gate || 'n/a') + '</div><div class="dl">Subject</div>' + val(b.subject) + '<div class="dl">Body</div>' + pre(b.body) + '</div></div>' +
      '<div class="grid2"><div><h4>What changed</h4><ul class="clean"><li>Score: ' + (a.score === null || b.score === null ? 'not measurable' : E(a.score) + ' &rarr; ' + E(b.score) + ' (' + (b.score - a.score >= 0 ? '+' : '') + E(Math.round((b.score - a.score) * 100) / 100) + ')') + '</li><li>Subject ' + (a.subject === b.subject ? 'unchanged' : 'changed') + '</li><li>Body length: ' + E(String(a.body || '').length) + ' &rarr; ' + E(String(b.body || '').length) + ' characters</li><li>Gate: ' + E(a.gate || 'n/a') + ' &rarr; ' + E(b.gate || 'n/a') + '</li></ul></div>' +
      '<div><h4>Reviewer findings and feedback</h4>' + list(c.versions.flatMap((v) => v.findings.map((f) => ({ v: v.version, f }))), (x) => 'v' + E(x.v) + ' <code>' + E(x.f.code) + '</code> (' + E(x.f.severity) + '): ' + E(x.f.explanation)) + '<h4>Revision feedback recorded</h4>' + list(fbs, (x) => 'After v' + E(x.v) + ' (' + E(x.f.source || 'reviewer_or_code') + '): ' + E(arr2(x.f.comments).join(' | '))) + '</div></div></div>';
  }).join('') : '<div class="card"><p class="empty">No case has more than one draft version yet, so no before/after comparison is shown. Single-version cases are not presented as improvements.</p></div>') + '</section>';
