// Do not let an old execution replay reset human-approval state or overwrite an approved version.
const n=$('Normalize Persistence Records').first().json;
const rows=$input.all().map(x=>x.json).filter(x=>x.case_id);
if(rows.length>1)throw new Error('Duplicate case keys block persistence.');
const c=rows[0];
if(c){
 if(c.case_id!==n.case_row.case_id)throw new Error('Persistence case mismatch.');
 if(c.first_recorded_at)n.case_row.first_recorded_at=c.first_recorded_at;
 if(c.approval_status&&c.approval_status!=='NOT_REQUESTED')throw new Error('This case already entered human approval. Refusing to rewrite its case/version records; use a new case.');
 if(c.gmail_draft_id)throw new Error('Existing Gmail draft blocks evidence replay.');
 if(Number(c.latest_version)>Number(n.case_row.latest_version))throw new Error('Refusing to overwrite newer draft history with an older replay.');
}
return [{json:n,pairedItem:{item:0}}];

// TRUSTED OWNER SETTINGS. Change only these values, not values inside meeting notes.
const settings = {
  enable_approval: true, // false = read-only preview; true = real Gmail approval request.
  case_id: 'AR2-21', // Choose an existing, normal, AI-reviewed case from AR_YD_Cases.
  reviewer_email: 'you@example.com', // Your own test Gmail inbox. One address only.
  draft_recipient: 'you@example.com', // Your own test Gmail inbox. One address only.
  collect_feedback_on_rejection: true,
  approval_wait_hours: 24,
  feedback_wait_hours: 24,
};
if(typeof settings.enable_approval!=='boolean'||typeof settings.collect_feedback_on_rejection!=='boolean')throw new Error('Approval toggles must be boolean true/false.');
if (!/^AR2-[A-Za-z0-9_-]+$/.test(settings.case_id)) throw new Error('Choose a saved AR2 case ID.');
for (const key of ['approval_wait_hours','feedback_wait_hours']) {
  if (!Number.isInteger(settings[key]) || settings[key] < 1 || settings[key] > 168) throw new Error('Wait limits must be whole hours from 1 to 168.');
}
return [{json:settings,pairedItem:{item:0}}];

// One saved case per execution. Never use meeting content to select recipients or authorization.
const cfg=$('Approval Settings').first().json;
const cases=$('Get Approval Case').all().map(x=>x.json).filter(x=>x.case_id);
const versions=$('Get Approval Versions').all().map(x=>x.json).filter(x=>x.record_key);
const events=$('Get Case Approval Events').all().map(x=>x.json).filter(x=>x.event_key);
const errors=[];
const fail=m=>errors.push(m);
const parse=x=>{if(typeof x!=='string')return x&&typeof x==='object'?x:null;try{return JSON.parse(x);}catch{return null;}};
const n=x=>typeof x==='number'&&Number.isFinite(x)?x:null;
const blank=x=>x===null||x===undefined||x==='';
const email=x=>typeof x==='string'&&x===x.trim()&&x.length<=254&&/^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?\.[A-Za-z]{2,}$/.test(x)&&!/[\r\n,;<>\s]/.test(x);
if(cases.length!==1)fail('Exactly one matching case row is required; none or duplicates were found.');
const c=cases[0]||{};
if(c.case_id!==cfg.case_id)fail('Case ID mismatch.');
if(c.review_status!=='AI_REVIEWED_NOT_HUMAN_APPROVED')fail('Only AI_REVIEWED_NOT_HUMAN_APPROVED cases are eligible.');
if(c.approval_status!=='NOT_REQUESTED')fail('This case is not in NOT_REQUESTED state. Reconcile previous requests instead of starting another.');
if(!blank(c.gmail_draft_id))fail('This case already has a Gmail draft ID.');
if(c.controlled_test!==false)fail('Controlled or unknown test provenance is not eligible for normal approval.');
if(!['LIVE_EXECUTION','REPLAY_OF_CAPTURED_EXECUTION'].includes(c.source_kind))fail('Case provenance is not a recorded execution.');
if(!Number.isInteger(c.latest_version)||c.latest_version<1||c.latest_version>3)fail('Invalid latest_version.');
if(versions.length===4)fail('Version read reached its safety limit.');
const selected=versions.filter(v=>v.case_id===cfg.case_id);
if(selected.some(v=>!Number.isInteger(v.version)||v.version<1||v.version>3))fail('Invalid saved version number.');
if(new Set(selected.map(v=>v.record_key)).size!==selected.length)fail('Duplicate version keys found.');
if(new Set(selected.map(v=>v.version)).size!==selected.length)fail('Duplicate version numbers found.');
if(!selected.length||Math.max(...selected.map(v=>v.version))!==c.latest_version)fail('Stored latest version does not match the version table.');
if(c.version_count!==selected.length)fail('Case/version row counts differ; persistence is incomplete.');
for(let i=1;i<=selected.length;i++)if(!selected.some(v=>v.version===i))fail('Version history is not contiguous.');
const v=selected.find(v=>v.version===c.latest_version)||{};
const review=parse(v.review_json),validation=parse(v.validation_json),evidence=parse(v.evidence_json),candidate=parse(v.evaluated_candidate_json);
if(v.record_key!==cfg.case_id+':v'+c.latest_version)fail('Latest record key is invalid.');
if(v.gate!=='PASS'||review?.gate!=='PASS'||review?.reviewer?.verdict!=='PASS')fail('Latest saved review did not pass.');
if(review?.score_valid!==true||review?.source_tool_verified!==true||evidence?.source_tool_verified!==true)fail('Valid review and real source-tool verification are required.');
const keys=['factual_accuracy','completeness','clarity','tone','safety'];
const scores=review?.reviewer?.scores;
if(!scores||keys.some(k=>!Number.isInteger(scores[k])||scores[k]<4||scores[k]>5)||scores?.factual_accuracy!==5||scores?.safety!==5)fail('Reviewer criterion scores do not meet the gate.');
const average=scores&&keys.every(k=>Number.isFinite(scores[k]))?keys.reduce((s,k)=>s+scores[k],0)/5:null;
